using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using Microsoft.EntityFrameworkCore;using OrcaFacil.Persistence;
namespace OrcaFacil.Web.Pages.SuperAdmin.Clients;[Authorize(Policy="SuperAdminOnly")]public sealed class UsageModel(OrcaFacilDbContext db):PageModel{public Guid ClientKey{get;private set;}public IReadOnlyList<Row>Items{get;private set;}=[];public async Task<IActionResult>OnGetAsync(Guid id,CancellationToken ct){if(!await db.BusinessAccounts.AnyAsync(x=>x.Id==id&&!x.IsDeleted,ct))return NotFound();ClientKey=id;Items=await db.AccountModuleUsageEvents.AsNoTracking().Where(x=>x.AccountId==id&&!x.IsDeleted).GroupBy(x=>x.ModuleCode).Select(g=>new Row(g.Key,g.Count(),g.Select(x=>x.UserId).Distinct().Count(),g.Max(x=>x.OccurredAt))).OrderByDescending(x=>x.Events).ToListAsync(ct);return Page();}public sealed record Row(string Module,int Events,int Users,DateTime Last);}
